448		batchSize := migrateFullBatchSize()
449		state := newMigrateLoopState(batchSize)
450	
451		// Span around the migration loop. No per-iteration spans: at 4k+ checkpoints
452		// the resulting attr count would blow past trace.go's 1MB scanner limit.
453		_, processSpan := perf.Start(ctx, "process_checkpoints")
454	
455		for _, info := range v1List {
456			existing, _, existingErr := readExistingV2Checkpoint(ctx, v2Store, existingV2, info.CheckpointID)
