557	// flushMain pushes any buffered /main entries through WriteCommittedMainBatch.
558	func (s *migrateLoopState) flushMain(ctx context.Context, v2Store *checkpoint.V2GitStore) error {
559		if len(s.pendingMain) == 0 {
560			return nil
561		}
562		if err := v2Store.WriteCommittedMainBatch(ctx, s.pendingMain); err != nil {
563			return fmt.Errorf("failed to write batched v2 /main entries: %w", err)
