569	// packCurrentBatch flushes /main, resolves the next archive slot if needed,
570	// then archives pendingFull into a /full/<n> ref.
571	func (s *migrateLoopState) packCurrentBatch(ctx context.Context, repo *git.Repository, v2Store *checkpoint.V2GitStore, batchSize int) error {
572		// Flush /main entries first so the index ref can never lag behind the
573		// data ref on a mid-batch crash.
574		if err := s.flushMain(ctx, v2Store); err != nil {
575			return err
576		}
577		if s.nextGeneration == 0 {
578			// Resolve the archive slot only when the first full batch is ready;
579			// force migration may prune existing archived refs earlier in the loop.
580			next, err := v2Store.NextGenerationNumber()
581			if err != nil {
582				return fmt.Errorf("list archived v2 generations: %w", err)
583			}
584			s.nextGeneration = next
585		}
586		refName := checkpoint.ArchivedGenerationRefName(s.nextGeneration)
587		archiveCommitHash, err := writeMigratedFullGeneration(ctx, repo, v2Store, refName, s.pendingFull)
588		if err != nil {
589			return fmt.Errorf("failed to pack migrated raw transcripts: %w", err)
590		}
591		if queueErr := queueMigratedFullGenerationPublication(ctx, v2Store, refName, archiveCommitHash); queueErr != nil {
592			// The archive ref and pending publication record must move together.
593			// If queueing fails, leave no archive ref behind so a retry can
594			// repack the generation and queue it again.
595			if removeErr := repo.Storer.RemoveReference(refName); removeErr != nil {
596				queueErr = fmt.Errorf("%w; failed to remove unqueued generation ref %s: %w", queueErr, refName, removeErr)
597			}
598			return fmt.Errorf("failed to queue migrated raw transcript generation for push: %w", queueErr)
599		}
600		s.writtenRefs = append(s.writtenRefs, refName)
601		s.nextGeneration++
602		s.pendingFull = make([]migratedFullCheckpoint, 0, batchSize)
603		return nil
604	}
