633	// sortMigratableCheckpoints sorts oldest-first so archived generations
634	// preserve chronological order. Zero timestamps sort last; CheckpointID
635	// breaks ties for deterministic reruns.
636	func sortMigratableCheckpoints(checkpoints []checkpoint.CommittedInfo) {
637		sort.SliceStable(checkpoints, func(i, j int) bool {
638			left := checkpoints[i].CreatedAt
639			right := checkpoints[j].CreatedAt
640			switch {
641			case left.IsZero() && right.IsZero():
642				return checkpoints[i].CheckpointID.String() < checkpoints[j].CheckpointID.String()
643			case left.IsZero():
644				return false
645			case right.IsZero():
646				return true
647			case left.Equal(right):
648				return checkpoints[i].CheckpointID.String() < checkpoints[j].CheckpointID.String()
649			default:
650				return left.Before(right)
651			}
652		})
653	}
