1210			return fmt.Errorf("failed to get v2 ref state for %s: %w", refName, err)
1211		}
1212	
1213		rootTree, err := repo.TreeObject(rootTreeHash)
1214		if err != nil {
1215			return fmt.Errorf("failed to read v2 tree for %s: %w", refName, err)
1216		}
1217		if _, err := rootTree.Tree(cpID.Path()); err != nil {
1218			return nil //nolint:nilerr // Checkpoint is absent from this ref, so there is nothing to prune.
1219		}
1220	
1221		shardPrefix := string(cpID[:2])
