1322	func pruneCheckpointFromRoot(repo *git.Repository, rootTreeHash plumbing.Hash, shardPrefix, shardSuffix string) (plumbing.Hash, error) {
1323		newRoot, err := checkpoint.UpdateSubtree(repo, rootTreeHash,
1324			[]string{shardPrefix},
1325			nil,
1326			checkpoint.UpdateSubtreeOptions{
1327				MergeMode:   checkpoint.MergeKeepExisting,
1328				DeleteNames: []string{shardSuffix},
1329			},
1330		)
1331		if err != nil {
1332			return plumbing.ZeroHash, fmt.Errorf("failed to prune checkpoint from shard: %w", err)
1333		}
1334		if newRoot == rootTreeHash {
1335			return newRoot, nil
1336		}
1337	
1338		newRootTree, err := repo.TreeObject(newRoot)
1339		if err != nil {
1340			return plumbing.ZeroHash, fmt.Errorf("failed to read pruned root tree: %w", err)
1341		}
1342		shardTree, err := newRootTree.Tree(shardPrefix)
1343		if err != nil {
1344			return newRoot, nil //nolint:nilerr // The shard prefix was already absent after pruning.
1345		}
1346		if len(shardTree.Entries) > 0 {
1347			return newRoot, nil
1348		}
1349	
1350		prunedRoot, err := checkpoint.UpdateSubtree(repo, rootTreeHash,
1351			nil,
1352			nil,
1353			checkpoint.UpdateSubtreeOptions{
