297	// v1CommitInfo carries the short hash and author time of the most recent
298	// commit on entire/checkpoints/v1 that touched a given checkpoint's folder.
299	// Either field can be zero/empty when the lookup fails.
300	type v1CommitInfo struct {
301		shortHash  string
302		authorTime time.Time
303	}
304	
305	// lookupV1CommitInfo returns the most recent commit on entire/checkpoints/v1
306	// that touched the checkpoint's sharded folder. We use path-scoped log rather
307	// than --grep so older subject formats and trailers-only matches still
308	// resolve. Failure (branch absent, no commit, parse error) returns a zero
309	// value — callers fall back to placeholder rendering.
310	func lookupV1CommitInfo(ctx context.Context, repoRoot string, cpID id.CheckpointID) v1CommitInfo {
311		if repoRoot == "" {
312			return v1CommitInfo{}
313		}
314		pathArg := string(cpID[:2]) + "/" + string(cpID[2:]) + "/"
315		gitCmd := exec.CommandContext(ctx, "git", "log", "entire/checkpoints/v1",
316			"-n", "1", "--pretty=%h %aI", "--", pathArg)
317		gitCmd.Dir = repoRoot
318		output, err := gitCmd.Output()
319		if err != nil {
320			return v1CommitInfo{}
321		}
322		line := strings.TrimSpace(string(output))
323		if line == "" {
324			return v1CommitInfo{}
325		}
326		fields := strings.SplitN(line, " ", 2)
327		if len(fields) == 0 {
328			return v1CommitInfo{}
329		}
330		info := v1CommitInfo{shortHash: fields[0]}
331		if len(fields) == 2 {
332			if t, err := time.Parse(time.RFC3339, fields[1]); err == nil {
333				info.authorTime = t
334			}
335		}
336		return info
337	}
