842	func writeMigratedFinalFullCurrent(ctx context.Context, repo *git.Repository, v2Store *checkpoint.V2GitStore, checkpoints []migratedFullCheckpoint) error {
843		if len(checkpoints) == 0 {
844			return nil
845		}
846	
847		refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
848		parentHash, rootTreeHash, err := v2Store.GetRefState(refName)
849		if err != nil && !errors.Is(err, plumbing.ErrReferenceNotFound) {
850			return fmt.Errorf("read v2 full/current ref: %w", err)
851		}
852	
853		entries := make(map[string]object.TreeEntry)
854		if rootTreeHash != plumbing.ZeroHash {
855			rootTree, err := repo.TreeObject(rootTreeHash)
856			if err != nil {
857				return fmt.Errorf("read v2 full/current tree: %w", err)
858			}
859			if err := checkpoint.FlattenTree(repo, rootTree, "", entries); err != nil {
860				return fmt.Errorf("flatten v2 full/current tree: %w", err)
861			}
862			delete(entries, paths.GenerationFileName)
863		}
864	
865		// Evict any pre-existing raw transcript artifacts for the sessions we're
866		// about to write so a shrinking chunk count can't leave stale .N files
867		// behind from a prior migration of the same checkpoint.
868		for _, cp := range checkpoints {
869			for _, session := range cp.sessions {
870				evictMigratedRawArtifacts(entries, cp.checkpointID, session.sessionIndex)
871			}
872		}
873		pendingEntries, err := buildMigratedFullEntrySet(ctx, repo, checkpoints)
874		if err != nil {
875			return fmt.Errorf("write migrated full/current entries: %w", err)
876		}
877		pendingEntries.mergeInto(entries)
878	
879		treeHash, err := checkpoint.BuildTreeFromEntries(ctx, repo, entries)
880		if err != nil {
881			return fmt.Errorf("build migrated full/current tree: %w", err)
882		}
883	
884		commitHash, err := checkpoint.CreateCommit(ctx, repo, treeHash, parentHash,
885			"Write migrated partial generation\n",
886			migrateAuthorName, migrateAuthorEmail)
887		if err != nil {
888			return fmt.Errorf("create migrated full/current commit: %w", err)
889		}
890	
891		return updateV2FullCurrentRef(ctx, repo, parentHash, commitHash)
892	}
