908	func createV2FullCurrentRefIfMissing(ctx context.Context, repo *git.Repository, refName plumbing.ReferenceName, newHash plumbing.Hash) error {
909		root, err := repoWorktreeRoot(repo)
910		if err != nil {
911			return fmt.Errorf("resolve worktree root for %s update: %w", refName, err)
912		}
913	
914		cmd := exec.CommandContext(ctx, "git", "update-ref", "--no-deref", refName.String(), newHash.String(), "")
915		cmd.Dir = root
916		output, err := cmd.CombinedOutput()
917		if err == nil {
918			return nil
919		}
920	
921		if currentRef, refErr := repo.Reference(refName, true); refErr == nil {
922			if currentRef.Hash() == newHash {
923				return nil
924			}
925			return fmt.Errorf("update %s: %w", refName, storage.ErrReferenceHasChanged)
926		}
927		if len(output) > 0 {
928			return fmt.Errorf("update %s: %w: %s", refName, err, strings.TrimSpace(string(output)))
929		}
930		return fmt.Errorf("update %s: %w", refName, err)
931	}
